using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using PowerShapeGeometry;

namespace PowerShapeBridge {
 // Read-only diagnostic; no selection/export callbacks and no authority to release a fence.
 internal static class OwnedGeometryExportVerification {
  internal interface IContext : DocumentBindings.IContext {Dictionary<string,object> ExportSettings();int Composite(int type,int id);}
  static void Require(bool ok,string error){if(!ok)throw new InvalidDataException(error);}
  static string Artifact(string root,string folder,object id){Require(EntitySets.Hex(id,32),"Fixed artifact ID required.");string path=Path.Combine(root,folder,(string)id+".json");OwnedCopies.NoReparse(path);return path;}
  static Dictionary<string,object>[] Array(object value){var list=value as IList;Require(list!=null,"Explicit proof array required.");return list.Cast<Dictionary<string,object>>().ToArray();}
  internal static void Validate(Dictionary<string,object> args) {
   string[] ids={"executionRequestId","inspectionRequestId","listingRequestId"},shas={"executionReceiptSha256","inspectionSha256","listingSha256"};Require(args.Count==9&&ids.All(k=>args.ContainsKey(k)&&EntitySets.Hex(args[k],32))&&shas.All(k=>args.ContainsKey(k)&&EntitySets.Hex(args[k],64))&&args.ContainsKey("windowNumber")&&args["windowNumber"] is int&&args.ContainsKey("modelId")&&args["modelId"] is int&&args.ContainsKey("expiresUtc"),"Exact independent export read references required.");EntitySets.Expiry(args["expiresUtc"]);
  }
  static void Fresh(OwnedGeometryExportTargets.TargetLease target,IContext context,Dictionary<string,object> expected,DateTime expiry,Dictionary<string,object>[] targets,Dictionary<string,object> settings,Dictionary<string,object> saved,Dictionary<string,object> diagnostics) {
   DocumentBindings.Check(target.Copy,expected,expiry,context,diagnostics,(string)target.Plan["windowContextSha256"]);
   foreach(var item in targets){var key=EntitySets.Keys(new[]{item["entityKey"]}).Single();Require(Equals(context.Composite(key[0],key[1]),item["compositeId"]),"Independent mapping differs.");}
   var observed=context.ExportSettings();OwnedGeometryExport.Settings(observed);Require(EntitySets.Canonical(observed)==EntitySets.Canonical(settings),"Independent export settings differ.");var files=WorkingCopyOpen.SavedHashes(context.Windows());Require(saved.Count==files.Count&&files.All(pair=>saved.ContainsKey(pair.Key)&&Equals(saved[pair.Key],pair.Value)),"Saved documents changed.");target.RecheckDependencies();context.ConfirmDocument();
  }
  internal static Dictionary<string,object> Verify(string root,string id,Dictionary<string,object> args,IContext context) {
   var result=new Dictionary<string,object>{{"state","owned_geometry_export_verification_rejected"},{"verificationId",id},{"exportAttempted",false},{"contextChangeAttempted",false},{"geometryMutationAttempted",false},{"cadSaveAttempted",false},{"geometryVerified",false},{"nativeProviderQualified",false},{"copyFenceReleased",false},{"retryAllowed",false}};
   try {
    Validate(args);Require(EntitySets.Hex(id,32),"Verification ID required.");
    using(var serial=new FileStream(Path.Combine(root,"operations","executor.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None))using(var proofs=new OwnedOperationPlans.Proofs()) {
     string executionId=(string)args["executionRequestId"];var receipt=proofs.Json(Artifact(root,"responses",executionId),(string)args["executionReceiptSha256"],16000000);
     Require(Equals(receipt["operationId"],executionId)&&Equals(receipt["state"],"owned_geometry_export_executed_unverified")&&Equals(receipt["exportAttempted"],true)&&Equals(receipt["contextChangeAttempted"],true)&&Equals(receipt["selectionRestoredObserved"],true)&&Equals(receipt["geometryVerified"],false)&&Equals(receipt["geometryMutationAttempted"],false)&&Equals(receipt["cadSaveAttempted"],false)&&Equals(receipt["nativeProviderQualified"],false)&&Equals(receipt["copyFenceReleased"],false),"Complete returned export receipt required; unknown is not resolved here.");
     var plan=proofs.Json(Artifact(root,"geometryexportexecutions",executionId),(string)receipt["planSha256"]);string[] fields={"targetId","targetSha256","schemaVersion","operationId","operation","copyId","ownershipSha256","workingSha256","targetPath","targets","settings","windowContextSha256","savedFileHashesBefore","createdUtc","qualification"};Require(plan.Count==fields.Length&&fields.All(plan.ContainsKey)&&Equals(plan["schemaVersion"],1)&&Equals(plan["operationId"],executionId)&&Equals(plan["operation"],"export_owned_geometry")&&EntitySets.Canonical(plan)==EntitySets.Canonical(receipt["plan"]),"Frozen export plan differs.");
     string journalFolder=Path.Combine(root,"operations",executionId);OwnedCopies.NoReparse(journalFolder);foreach(string path in Directory.GetFiles(journalFolder,"*.json"))proofs.Json(path,null);var journal=NativeJournal.ForVerification(root,executionId,(string)receipt["planSha256"]);Require(journal.State=="executed_unverified"&&Equals(journal.CommandReturnedDetails["exportCallbackReturned"],true)&&Equals(journal.CommandReturnedDetails["nativeReturnCodeQualified"],false),"Export journal lacks complete unqualified callback return.");
     using(var target=new OwnedGeometryExportTargets.TargetLease(root,(string)plan["targetId"],(string)plan["targetSha256"],true)) {
      foreach(string key in new[]{"copyId","ownershipSha256","workingSha256","targetPath","windowContextSha256"})Require(Equals(plan[key],target.Plan[key]),"Export target dependency differs.");Require(EntitySets.Expiry(plan["createdUtc"])>=EntitySets.Expiry(target.Plan["preparedUtc"])&&EntitySets.Expiry(plan["createdUtc"])<=journal.CommandReturnedUtc,"Export plan chronology differs.");
      var targets=Array(plan["targets"]);Require(targets.Length==target.Source.Keys.Length&&targets.Length>0&&targets.Length<=128,"Export target count differs.");var inventory=EntitySets.Inventory(target.Source.Expected);for(int index=0;index<targets.Length;index++){var key=target.Source.Keys[index];var item=inventory.Single(e=>Equals(e["nativeTypeCode"],key[0])&&Equals(e["nativeId"],key[1]));Require(targets[index].Count==5&&targets[index].ContainsKey("compositeId")&&targets[index]["compositeId"] is int&&(int)targets[index]["compositeId"]>0&&EntitySets.Canonical(targets[index]["entityKey"])==EntitySets.Canonical(key)&&Equals(targets[index]["type"],item["type"])&&Equals(targets[index]["name"],item["name"])&&Equals(targets[index]["levelNumber"],item["levelNumber"]),"Selection target/order differs from source.");}Require(targets.Select(t=>t["compositeId"]).Distinct().Count()==targets.Length,"Duplicate direct export mapping.");
      var settings=(Dictionary<string,object>)plan["settings"];OwnedGeometryExport.Settings(settings);string folder=OwnedGeometryExportTargets.Folder(root,(string)plan["targetId"]);
      var claim=proofs.Json(Path.Combine(folder,"export-once.json"),null);Require(claim.Count==4&&Equals(claim["operationId"],executionId)&&Equals(claim["planSha256"],receipt["planSha256"])&&Equals(claim["targetId"],plan["targetId"])&&Equals(claim["automaticReplayForbidden"],true),"Export claim differs.");string fencePath=OwnedGeometryExportTargets.ExportFencePath(root,(string)plan["copyId"]);var fence=proofs.Json(fencePath,(string)receipt["exportFenceSha256"]);Require(fence.Count==6&&Equals(fence["schemaVersion"],1)&&Equals(fence["operationId"],executionId)&&Equals(fence["planSha256"],receipt["planSha256"])&&Equals(fence["copyId"],plan["copyId"])&&Equals(fence["ownershipSha256"],plan["ownershipSha256"])&&Equals(fence["automaticReplayForbidden"],true),"Original export fence differs.");
      var summary=proofs.Json(Path.Combine(folder,"export-summary.json"),(string)receipt["summarySha256"]);Require(Equals(summary["operationId"],executionId)&&Equals(summary["planSha256"],receipt["planSha256"])&&Equals(summary["outputSha256"],receipt["outputSha256"])&&Equals(summary["geometryVerified"],false)&&Equals(journal.LastDetails["summarySha256"],receipt["summarySha256"]),"Journal/summary/file linkage differs.");var commands=Array(summary["commands"]);Require(commands.Length==targets.Length+2&&Equals(journal.CommandReturnedDetails["callbackCalls"],commands.Length)&&Equals(receipt["callbackCallsAttempted"],commands.Length),"Incomplete callback sequence.");
      for(int index=0;index<commands.Length;index++) {
       string kind=index<targets.Length?"add_selection":index==targets.Length?"export_dmt":"clear_own_selection";var command=commands[index];Require(Equals(command["index"],index)&&Equals(command["kind"],kind),"Command order differs.");string prefix=Path.Combine(folder,index.ToString("D6"));var started=proofs.Json(prefix+".started.json",(string)command["startedSha256"]);var returned=proofs.Json(prefix+".returned.json",(string)command["returnedSha256"]);
       Require(Equals(started["operationId"],executionId)&&Equals(returned["operationId"],executionId)&&Equals(started["planSha256"],receipt["planSha256"])&&Equals(returned["planSha256"],receipt["planSha256"])&&Equals(started["index"],index)&&Equals(returned["index"],index)&&Equals(started["kind"],kind)&&Equals(returned["kind"],kind)&&Equals(returned["startedSha256"],command["startedSha256"])&&Equals(returned["callbackReturned"],true),"Per-step callback proof differs.");if(index<targets.Length)Require(EntitySets.Canonical(started["target"])==EntitySets.Canonical(targets[index]),"Selected target differs.");else if(index==targets.Length)Require(Equals(started["path"],plan["targetPath"]),"Export path differs.");
      }
      var expected=proofs.Json(Artifact(root,"responses",args["inspectionRequestId"]),(string)args["inspectionSha256"],16000000);var listing=proofs.Json(Artifact(root,"responses",args["listingRequestId"]),(string)args["listingSha256"],16000000);var expiry=EntitySets.Expiry(args["expiresUtc"]);EntitySets.CheckObserved(expected,expected,target.Source.Keys,expiry,DateTime.UtcNow);Require(EntitySets.Expiry(expected["timestampUtc"])>journal.CommandReturnedUtc&&EntitySets.Expiry(listing["timestampUtc"])>journal.CommandReturnedUtc&&expiry<=EntitySets.Expiry(listing["timestampUtc"]).AddSeconds(300)&&Equals(listing["state"],"documents_listed_verified"),"Independent reads must follow export completion.");Require(EntitySets.ObservedDigest(expected)==EntitySets.ObservedDigest(target.Source.Expected)&&DocumentBindings.WindowDigest(listing)==(string)plan["windowContextSha256"],"Post-export source/context differs.");var active=(Dictionary<string,object>)listing["activeWindow"];Require(Equals(active["windowNumber"],args["windowNumber"])&&Equals(active["modelId"],args["modelId"]),"Independent active choice differs.");
      var saved=(Dictionary<string,object>)plan["savedFileHashesBefore"];Fresh(target,context,expected,expiry,targets,settings,saved,result);string outputPath=(string)plan["targetPath"];OwnedCopies.NoReparse(outputPath);using(var file=new FileStream(outputPath,FileMode.Open,FileAccess.Read,FileShare.Read)) {
       var identity=OwnedCopies.FileIdentity(file,outputPath,true);Require(EntitySets.Canonical(identity)==EntitySets.Canonical(summary["outputFileIdentity"]),"Independent export file identity differs.");var mesh=DmtMeshReader.Read(file);string sha=OwnedCopies.Digest(file);Require(sha==(string)receipt["outputSha256"]&&Equals(mesh.VertexCount,receipt["vertexCount"])&&Equals(mesh.TriangleCount,receipt["triangleCount"])&&Equals(mesh.LengthUnits,receipt["meshLengthUnits"]),"Independent output bytes/mesh differs.");Fresh(target,context,expected,expiry,targets,settings,saved,result);Require(OwnedCopies.Digest(file)==sha&&EntitySets.Canonical(OwnedCopies.FileIdentity(file,outputPath,true))==EntitySets.Canonical(identity),"Output changed during verification.");
       var diagnostic=new Dictionary<string,object>{{"schemaVersion",1},{"verificationId",id},{"executionRequestId",executionId},{"executionReceiptSha256",args["executionReceiptSha256"]},{"planSha256",receipt["planSha256"]},{"inspectionRequestId",args["inspectionRequestId"]},{"inspectionSha256",args["inspectionSha256"]},{"listingRequestId",args["listingRequestId"]},{"listingSha256",args["listingSha256"]},{"outputSha256",sha},{"outputFileIdentity",identity},{"state","observed_export_file_context_match_unqualified"},{"vertexCount",mesh.VertexCount},{"triangleCount",mesh.TriangleCount},{"lengthUnits",mesh.LengthUnits},{"coordinateFrame","file_coordinates_unqualified"},{"copyFenceReleased",false},{"geometryVerified",false},{"nativeProviderQualified",false}};string path=Artifact(root,"geometryexportverifications",id);Directory.CreateDirectory(Path.GetDirectoryName(path));result["diagnosticSha256"]=NativeJournal.Freeze(path,diagnostic);result["state"]=diagnostic["state"];result["fileAndContextObservedMatch"]=true;result["recordedJournalState"]=journal.State;
      }
     }
    }
   }catch(Exception error){result["error"]=error.Message;}
   result["timestampUtc"]=DateTime.UtcNow.ToString("o");return result;
  }
 }
}
